int uniquePathsWithObstacles(int **obstacleGrid, int obstacleGridSize, int *obstacleGridColSize) {
  int m = obstacleGridSize, n = obstacleGridColSize[0];
  int *dp = (int *)calloc(n, sizeof(int));
  dp[0] = obstacleGrid[0][0] == 0 ? 1 : 0;
  for (int j = 1; j < n; j++) dp[j] = obstacleGrid[0][j] == 0 ? dp[j - 1] : 0;
  for (int i = 1; i < m; i++) {
    if (obstacleGrid[i][0]) dp[0] = 0;
    for (int j = 1; j < n; j++) {
      if (obstacleGrid[i][j]) {
        dp[j] = 0;
      } else {
        dp[j] += dp[j - 1];
      }
    }
  }
  int res = dp[n - 1];
  free(dp);
  return res;
}

class Solution {
public:
  int uniquePathsWithObstacles(vector<vector<int>> &obstacleGrid) {
    int m = obstacleGrid.size(), n = obstacleGrid[0].size();
    vector<long long> dp(n, 0);
    dp[0] = obstacleGrid[0][0] == 0 ? 1 : 0;
    for (int j = 1; j < n; j++) dp[j] = obstacleGrid[0][j] == 0 ? dp[j - 1] : 0;
    for (int i = 1; i < m; i++) {
      if (obstacleGrid[i][0]) dp[0] = 0;
      for (int j = 1; j < n; j++) {
        if (obstacleGrid[i][j]) {
          dp[j] = 0;
        } else {
          dp[j] += dp[j - 1];
        }
      }
    }
    return (int)dp[n - 1];
  }
};

func uniquePathsWithObstacles(obstacleGrid [][]int) int {
	m, n := len(obstacleGrid), len(obstacleGrid[0])
	dp := make([]int, n)
	if obstacleGrid[0][0] == 0 {
		dp[0] = 1
	}
	for j := 1; j < n; j++ {
		if obstacleGrid[0][j] == 0 {
			dp[j] = dp[j-1]
		}
	}
	for i := 1; i < m; i++ {
		if obstacleGrid[i][0] == 1 {
			dp[0] = 0
		}
		for j := 1; j < n; j++ {
			if obstacleGrid[i][j] == 1 {
				dp[j] = 0
			} else {
				dp[j] += dp[j-1]
			}
		}
	}
	return dp[n-1]
}

class Solution {
  public int uniquePathsWithObstacles(int[][] obstacleGrid) {
    int m = obstacleGrid.length, n = obstacleGrid[0].length;
    long[] dp = new long[n];
    dp[0] = obstacleGrid[0][0] == 0 ? 1 : 0;
    for (int j = 1; j < n; j++) dp[j] = obstacleGrid[0][j] == 0 ? dp[j - 1] : 0;
    for (int i = 1; i < m; i++) {
      if (obstacleGrid[i][0] == 1) dp[0] = 0;
      for (int j = 1; j < n; j++) {
        if (obstacleGrid[i][j] == 1) {
          dp[j] = 0;
        } else {
          dp[j] += dp[j - 1];
        }
      }
    }
    return (int) dp[n - 1];
  }
}

class Solution:
    def uniquePathsWithObstacles(self, obstacleGrid: List[List[int]]) -> int:
        m, n = len(obstacleGrid), len(obstacleGrid[0])
        dp = [0] * n
        dp[0] = 0 if obstacleGrid[0][0] else 1
        for j in range(1, n):
            dp[j] = dp[j - 1] if obstacleGrid[0][j] == 0 else 0
        for i in range(1, m):
            if obstacleGrid[i][0]:
                dp[0] = 0
            for j in range(1, n):
                dp[j] = 0 if obstacleGrid[i][j] else dp[j] + dp[j - 1]
        return dp[n - 1]

impl Solution {
  pub fn unique_paths_with_obstacles(obstacle_grid: Vec<Vec<i32>>) -> i32 {
    let m = obstacle_grid.len();
    let n = obstacle_grid[0].len();
    let mut dp = vec![0i64; n];
    dp[0] = if obstacle_grid[0][0] == 0 { 1 } else { 0 };
    for j in 1..n {
      dp[j] = if obstacle_grid[0][j] == 0 { dp[j - 1] } else { 0 };
    }
    for i in 1..m {
      if obstacle_grid[i][0] == 1 {
        dp[0] = 0;
      }
      for j in 1..n {
        dp[j] = if obstacle_grid[i][j] == 1 { 0 } else { dp[j] + dp[j - 1] };
      }
    }
    dp[n - 1] as i32
  }
}

const uniquePathsWithObstacles = (obstacleGrid: number[][]): number => {
  const m = obstacleGrid.length;
  const n = obstacleGrid[0].length;
  const dp: number[] = new Array(n).fill(0);
  dp[0] = obstacleGrid[0][0] === 0 ? 1 : 0;
  for (let j = 1; j < n; j++) dp[j] = obstacleGrid[0][j] === 0 ? dp[j - 1] : 0;
  for (let i = 1; i < m; i++) {
    if (obstacleGrid[i][0] === 1) dp[0] = 0;
    for (let j = 1; j < n; j++) {
      dp[j] = obstacleGrid[i][j] === 1 ? 0 : dp[j] + dp[j - 1];
    }
  }
  return dp[n - 1];
};
